USE [Hyperyek]; IF OBJECT_ID(N'dbo.IntegrationWebhookInbox',N'U') IS NULL CREATE TABLE dbo.IntegrationWebhookInbox (Id bigint IDENTITY PRIMARY KEY,ConnectionId bigint NOT NULL,ExternalEventId nvarchar(200) NOT NULL,EventType nvarchar(200) NOT NULL,PayloadJson nvarchar(max) NOT NULL,ReceivedAtUtc datetime2 NOT NULL DEFAULT SYSUTCDATETIME(),ProcessedAtUtc datetime2 NULL,Status tinyint NOT NULL DEFAULT(0),Error nvarchar(4000) NULL,CONSTRAINT UQ_IntegrationWebhookInbox UNIQUE(ConnectionId,ExternalEventId),CONSTRAINT FK_IntegrationWebhookInbox_Connection FOREIGN KEY(ConnectionId) REFERENCES dbo.ExternalIntegrationConnections(Id));
